import{_ as l,C as e,c as i,o as n,aa as s,G as r}from"./chunks/framework.Cn7WEiMX.js";const h="/assets/virtual-reality-dynmap-example.D9X1YkL5.png",k=JSON.parse('{"title":"附属","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/addons.md","filePath":"wiki/Dynmap/addons.md"}'),p={name:"wiki/Dynmap/addons.md"};function d(c,a,m,u,b,y){const t=e("NolebaseGitContributors"),o=e("NolebaseGitChangelog");return n(),i("div",null,[a[0]||(a[0]=s('<h1 id="附属" tabindex="-1">附属 <a class="header-anchor" href="#附属" aria-label="Permalink to &quot;附属&quot;">​</a></h1> <h2 id="本页包含所有已知的-dynmap-附属" tabindex="-1">本页包含所有已知的 Dynmap 附属 <a class="header-anchor" href="#本页包含所有已知的-dynmap-附属" aria-label="Permalink to &quot;本页包含所有已知的 Dynmap 附属&quot;">​</a></h2> <div class="tip custom-block"><p class="custom-block-title">提示</p> <p>所有附属都由社区开发，不会在这个 Github 仓库或者 Dynmap Discord 聊天群组中受官方 Dynamp 开发团队的支持。所有有关附属的安装、配置或调试的问题应当联系对应的附属作者或其维护者。如果你想要将你的插件加入这个列表，请按已有格式自行添加，或联系 Discord 上的管理员协助你添加。</p></div> <p>本页可分为两部分：活跃和弃坑附属。活跃附属即时常更新并支持最新版本 Dynmap/Minecraft 的附属，和/或有着活跃维护者。如果某个附属仍然生效但长时间不维护，且无法联系开发者支持，它就会被列入弃坑附属中，仅作历史记录与旧版本兼容用。</p> <h2 id="活跃附属" tabindex="-1">活跃附属 <a class="header-anchor" href="#活跃附属" aria-label="Permalink to &quot;活跃附属&quot;">​</a></h2> <h3 id="网页界面修改" tabindex="-1">网页界面修改 <a class="header-anchor" href="#网页界面修改" aria-label="Permalink to &quot;网页界面修改&quot;">​</a></h3> <h4 id="liveatlas" tabindex="-1"><a href="https://www.spigotmc.org/resources/86939/" target="_blank" rel="noreferrer">LiveAtlas</a> <a class="header-anchor" href="#liveatlas" aria-label="Permalink to &quot;[LiveAtlas](https://www.spigotmc.org/resources/86939/)&quot;">​</a></h4> <blockquote><p>LiveAtlas 是 Dynmap 或 Pl3xmap 的界面替代，专注于为用户带来更现代的外观及密集地图下的性能提升。LiveAtlas 开箱即用，可替代 Dynmap 或 Pl3xmap，另外后者的地图只需少许修改即可兼容。</p></blockquote> <ul><li>开发者：<a href="https://github.com/JLyne" target="_blank" rel="noreferrer">https://github.com/JLyne</a></li> <li>源代码：<a href="https://github.com/JLyne/LiveAtlas" target="_blank" rel="noreferrer">https://github.com/JLyne/LiveAtlas</a></li> <li>插件维基：<a href="https://github.com/JLyne/LiveAtlas/wiki" target="_blank" rel="noreferrer">https://github.com/JLyne/LiveAtlas/wiki</a></li> <li>获取帮助：<a href="https://github.com/JLyne/LiveAtlas/issues" target="_blank" rel="noreferrer">https://github.com/JLyne/LiveAtlas/issues</a></li> <li>支持作者：<a href="https://ko-fi.com/jlyne" target="_blank" rel="noreferrer">https://ko-fi.com/jlyne</a></li></ul> <h4 id="material-dynmap" tabindex="-1"><a href="https://github.com/SNDST00M/material-dynmap" target="_blank" rel="noreferrer">Material-Dynmap</a> <a class="header-anchor" href="#material-dynmap" aria-label="Permalink to &quot;[Material-Dynmap](https://github.com/SNDST00M/material-dynmap)&quot;">​</a></h4> <blockquote><p>现代的、使用了 Material UI 并专注于 Webbukkit 的 Dynmap 主题。侧重于通过 Material Design 表达流畅与清爽风格的导航界面。</p></blockquote> <ul><li>开发者：<a href="https://github.com/SNDST00M/" target="_blank" rel="noreferrer">https://github.com/SNDST00M/</a></li> <li>源代码：<a href="https://github.com/SNDST00M/material-dynmap" target="_blank" rel="noreferrer">https://github.com/SNDST00M/material-dynmap</a></li> <li>插件维基：<a href="https://github.com/SNDST00M/material-dynmap/wiki" target="_blank" rel="noreferrer">https://github.com/SNDST00M/material-dynmap/wiki</a></li> <li>获取帮助：<a href="https://github.com/SNDST00M/material-dynmap/issues" target="_blank" rel="noreferrer">https://github.com/SNDST00M/material-dynmap/issues</a></li> <li>支持作者：<a href="https://www.patreon.com/dynmap/" target="_blank" rel="noreferrer">https://www.patreon.com/dynmap/</a></li></ul> <h3 id="渲染器" tabindex="-1">渲染器 <a class="header-anchor" href="#渲染器" aria-label="Permalink to &quot;渲染器&quot;">​</a></h3> <h4 id="chunkymap" tabindex="-1">ChunkyMap <a class="header-anchor" href="#chunkymap" aria-label="Permalink to &quot;ChunkyMap&quot;">​</a></h4> <p><a href="https://github.com/leMaik/ChunkyMap" target="_blank" rel="noreferrer">ChunkyMap</a> 是一个“结合了照片写实之便利与 Dynmap 自动更新特性”的地图渲染器。</p> <p>ChunkyMap 开箱即用，可替换 Dynmap 自带的 <code>HDMap</code> 渲染方式。</p> <h3 id="插件对接" tabindex="-1">插件对接 <a class="header-anchor" href="#插件对接" aria-label="Permalink to &quot;插件对接&quot;">​</a></h3> <h4 id="dynmap-towny" tabindex="-1"><a href="https://github.com/TownyAdvanced/Dynmap-Towny" target="_blank" rel="noreferrer">Dynmap-Towny</a> <a class="header-anchor" href="#dynmap-towny" aria-label="Permalink to &quot;[Dynmap-Towny](https://github.com/TownyAdvanced/Dynmap-Towny)&quot;">​</a></h4> <ul><li>开发者：<a href="https://github.com/TownyAdvanced/" target="_blank" rel="noreferrer">https://github.com/TownyAdvanced/</a></li> <li>源代码：<a href="https://github.com/TownyAdvanced/Dynmap-Towny" target="_blank" rel="noreferrer">https://github.com/TownyAdvanced/Dynmap-Towny</a></li> <li>插件维基：<a href="https://github.com/hankjordan/Dynmap-Towny/wiki" target="_blank" rel="noreferrer">https://github.com/hankjordan/Dynmap-Towny/wiki</a></li> <li>获取帮助：<a href="https://discord.gg/gnpVs5m" target="_blank" rel="noreferrer">https://discord.gg/gnpVs5m</a></li> <li>支持作者：<a href="https://github.com/sponsors/LlmDl" target="_blank" rel="noreferrer">https://github.com/sponsors/LlmDl</a></li></ul> <div class="tip custom-block"><p class="custom-block-title">提示</p> <p>SiegeWar 的配置包括了“隐藏地图”，会覆盖 Dynmap 的配置以抹去玩家在郊区/地下/被攻占区域的位置显示。这可能看起来像玩家会“随机地”在地图上不显示其位置。</p></div> <h4 id="worldborder" tabindex="-1"><a href="https://dev.bukkit.org/projects/worldborder" target="_blank" rel="noreferrer">WorldBorder</a> <a class="header-anchor" href="#worldborder" aria-label="Permalink to &quot;[WorldBorder](https://dev.bukkit.org/projects/worldborder)&quot;">​</a></h4> <p>使得 Dynmap 能够预先生成与渲染世界。Dynmap 只显示生成的区块，因此它有相当明显的优势。</p> <div class="tip custom-block"><p class="custom-block-title">提示</p> <ul><li>WorldBorder 只会在输入命令后生成区块。</li> <li>Dynmap 会自动显示边界。你需要配置 Dynmap 的可视区域与 WB 边界大小相同。</li> <li>如果你已经生成了超出边界的区域，你可以使用命令 <code>dynmap purgemap</code> 进行清理。</li></ul></div> <h4 id="skinrestorer" tabindex="-1">SkinRestorer <a class="header-anchor" href="#skinrestorer" aria-label="Permalink to &quot;SkinRestorer&quot;">​</a></h4> <p>SkinRestorer 是一个为离线模式服务器保存皮肤的插件，同时使得玩家能通过一条简单的命令切换皮肤。</p> <p>开发者直接提供了代码，但 Dynmap 无法直接支持 - 请告诉他们。</p> <h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3> <h4 id="earthmc" tabindex="-1">EarthMC <a class="header-anchor" href="#earthmc" aria-label="Permalink to &quot;EarthMC&quot;">​</a></h4> <p>EarthMC 是一个涉及了部分插件的<strong>地图企划</strong>。</p> <p>在 2021 年 12 月，Discord 群组聊天内提及 EarthMC 相关问题时有如下信息：</p> <blockquote><p>EarthMC 地图与 Dynmap 有着许多已知问题，如渲染不完整，只渲染玩家所到之处，或者不渲染树叶和其他植物。这个问题与地图制作的过程有关，而与插件本身无关，但好在这里有解决办法：</p> <ol><li>安装 WorldBorder 插件：<a href="https://www.spigotmc.org/resources/worldborder.60905/" target="_blank" rel="noreferrer">https://www.spigotmc.org/resources/worldborder.60905/</a></li> <li>通过命令暂停 Dynmap：<code>/dynmap pause all</code></li> <li>以强制参数运行 WorldBorder：<code>/wb [世界名称] fill [频率] [界限外数量] [是否强制]</code></li></ol> <ul><li><code>[世界名称]</code> 即为世界所在文件夹的名称</li> <li><code>[频率]</code> 即为每秒生成多少区块，默认为 20。警告：过高值会导致服务器卡顿。</li> <li><code>[界限外数量]</code> 即为在边界外再生成多少区块，这可以确保玩家到达边界时邻近所有地形都已生成。默认为 208，不过在 EarthMC 中我推荐将其设置为 0。</li> <li><code>[是否强制]</code> 选项必须设置为 true。</li></ul> <ol start="4"><li>等待插件完成地形生成</li> <li>通过命令 <code>/dynmap pause none</code> 解除 Dynmap 的暂停，你还可能需要通过命令 <code>/dynmap fullrender [世界名称]</code> 重置完全渲染器。</li></ol></blockquote> <h4 id="virtual-realiy-简单地皮与高级世界保护" tabindex="-1">Virtual Realiy - 简单地皮与高级世界保护 <a class="header-anchor" href="#virtual-realiy-简单地皮与高级世界保护" aria-label="Permalink to &quot;Virtual Realiy - 简单地皮与高级世界保护&quot;">​</a></h4> <p>Virtual Reality 是一款简单医用的服务器插件，允许玩家创建自己的地皮，为其好友添加信任，建造自己想要的建筑，防止熊孩子破坏，甚至可以切换到预设游戏模式，并在离开时回到原本的模式！</p> <figure><img src="'+h+'" alt="image" tabindex="0"><figcaption>image</figcaption></figure> <h3 id="混合端" tabindex="-1">混合端 <a class="header-anchor" href="#混合端" aria-label="Permalink to &quot;混合端&quot;">​</a></h3> <p>Cardboard、Magma 以及其他为 Forge 和 Fabric 同时提供兼容的模组。</p> <p>截至目前，混合端尚未支持。见<a href="https://github.com/webbukkit/dynmap/issues/3482#issuecomment-986661674" target="_blank" rel="noreferrer">标记为“不会修复”的议题</a>获悉详情（2021 年 12 月）。</p> <p>相似的是，尝试为 Java 版和基岩版提供支持的 Geyser 会使得部分无效名称的玩家可以进入服务器。见<a href="https://github.com/webbukkit/dynmap/issues/3514" target="_blank" rel="noreferrer">相关议题</a>。</p> <h2 id="弃坑附属" tabindex="-1">弃坑附属 <a class="header-anchor" href="#弃坑附属" aria-label="Permalink to &quot;弃坑附属&quot;">​</a></h2> <ul><li>弃坑：原 ~Webbukkit Dynmap Towny 附属~ 自 2016 年起便停止更新。请使用上述“TownyAdvanced”分支。</li> <li>弃坑：<a href="https://www.spigotmc.org/resources/abandoned-clans-dynmap-addon-for-clans-free.87028" target="_blank" rel="noreferrer">~Dynmap Addon for Clans~</a></li> <li>状态未知：<a href="https://dev.bukkit.org/projects/dynmap-pylandmarks" target="_blank" rel="noreferrer">~dynmap PyLandmarks~</a></li> <li>...以及其他<strong>未受</strong> Dynamp 开发者<strong>维护</strong>的插件。</li></ul> ',80)),r(t),r(o)])}const f=l(p,[["render",d]]);export{k as __pageData,f as default};
